om: 0.5rem;\n                    }\n                    .small-line {\n                        pointer-events: none;\n                        font-size: 13px;\n                        color: #fff !important;\n                        * {\n                            color: #fff !important;\n                        }\n                        a {\n                            text-decoration: underline;\n                        }\n                        @media only screen and (min-width: 450px) {\n                            font-size: 16px;\n                        }\n                    }\n                }\n                &.is-active {\n                    cursor: zoom-out;\n                    .work-example-image-caption {\n                        opacity: 0.97 !important;\n                    }\n                    .small-line {\n                        pointer-events: auto;\n                    }\n                }\n            }\n        }\n    }\n}\n","\nbody.theme-sun {\n    background-color: $colour_light_grey_aotrom!important;\n    blockquote.main-quote {\n        p {\n            .shiner.smaller {\n                display: none !important;\n                animation: none !important;\n            }\n        }\n    }\n}\nbody[data-theme=\"theme-sun\"] {\n    background-color: $colour_light_grey_aotrom!important;\n}\n","body {\n    transition: background-color 0.3s ease;\n    background-color: $colour_yep_thats_grey;\n}\nbody.theme-rocket {\n    &.has-video {\n        background-color: $colour_black;\n    }\n    &.header-0 {\n        background-color: $colour_yep_thats_grey;\n    }\n\n\n    a[data-add-class=\"theme-rocket\"] {\n        text-decoration: none !important;\n    }\n    #main {\n        blockquote.main-quote {\n            position: fixed;\n            margin-top: 0 !important;\n            p {\n                filter: drop-shadow(0 0 6px #000);\n                background: none;\n                color: $colour_white !important;\n                *