xample-images {\n                p.caption {\n                    a {\n                        color: #333 !important;\n                        &:link,\n                        &:visited {\n                            color: #333 !important;\n                            border-color: $colour_burned_sunny_side_up_thirty_percent;\n                        }\n                    }\n                }\n            }\n        }\n    }\n    #Breadcrumbs {\n        border-color: $colour_burned_sunny_side_up_thirty_percent !important;\n    }\n    footer#footer {\n        background-color: $colour_boot_black_semi;\n        img {\n            // filter: invert(1);\n        }\n        * {\n            color: $colour_white;\n        }\n        p {\n            color: $colour_white;\n        }\n        li.current a,\n        a:hover {\n            color: $colour_ekos_green !important;\n        }\n        #theme-selectors {\n            svg {\n                fill: $colour_white;\n                &:hover {\n                    fill: $colour_ekos_green !important;\n                }\n            }\n            #theme-moon {\n                svg {\n                    fill: $colour_ekos_green !important;\n                }\n            }\n        }\n    }\n    &.past-header {\n        #header {\n            border-color: #fff !important;\n            background-color: $colour_burned_sunny_side_up;\n            // &:before {\n            //     border-top-color:  #000000c4;\n            // }\n            * {\n                color: #fff;\n            }\n            .page-title {\n                color: $colour_white;\n            }\n        }\n        #nav {\n            background-color: transparent;\n        }\n    }\n    #BackgroundVideo {\n        background-color: $colour_black;\n    }\n    main#main {\n        blockquote.main-quote {\n            p {\n                color: $colour_overcast_sunny_side_up !important;\n                * {\n                    color: $colour_overcast_sunny_side_up !important;\n                }\n            }\n        }\n    }\n}\n/** importantly this applies top to bottom */\nbody[data-theme=\"theme-moon\"] {\n    background-color: $colour_sunny_side_up_dark_purple !important;\n    &.menu-on {\n        #header {\n            * {\n                color: $colour_sunny_side_up_yellow !important;\n            }\n        }\n        #nav {\n            #nav-inner {\n                ul {\n                    li {\n                        a {\n                            &:hover {\n                                border-bottom: 3px solid $colour_sunny_side_up_green !important;\n                            }\n                        }\n                        &.current > a {\n                            border-bottom: 3px solid $colour_sunny_side_up_green !important;\n                        }\n                    }\n                }\n            }\n\n            background-color: $colour_purple_spirituality_in_the_sun;\n            * {\n                color: $colour_sunny_side_up_green;\n            }\n            i {\n                background-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A//www.w3.org/2000/svg'%20viewBox%3D'23.5%2022.5%2031%2029'%3E%3Cpath%20d%3D'M26%2037H50%20M40%2025L52%2037L40%2049'%20fill%3D'none'%20stroke%3D'%2300ab06'%20stroke-width%3D'5'%20stroke-linecap%3D'round'%20stroke-linejoin%3D'round'/%3E%3C/svg%3E\");\n            }\n\n            #closed-icon {\n                .cls-1 {\n                    fill: $colour_patrick_star_skin_colour;\n                }\n                .cls-2 {\n                    fill: $colour_white;\n                }\n            }\n            #open-icon {\n                .cls-1 {\n                    fill: $colour_rose_storm;\n                }\n                .cls-2 {\n                    fill: $colour_white;\n                }\n            }\n        }\n    }\n}\n\n@media only screen and (min-width: 1050px) {\n    body.theme-moon,\n    body.theme-moon.past-header {\n        #nav {\n            background-color: $colour_outer_space_love;\n        }\n        .menu-arrow {\n            stroke: $colour_outer_space_love !important;\n        }\n    }\n}\nbody.theme-moon.has-bg-image-loaded {\n\n    #header {\n        * {\n            color: $colour_burned_sunny_side_up;\n        }\n    }\n}\n","blockquote.main-quote,\ntheme-rocket #main #content-below-quote *,\nfooter {\n    transition:\n        color 0.1s ease-in-out,\n        opacity 0.1s ease-in-out,\n        background-size 0.1s ease-in-out !important;\n}\nbody.header-0 {\n    #BackgroundImage.has-bg-image-loaded,\n    blockquote.main-quote {\n        opacity: 1 !important;\n    }\n    #header {\n        zoom: 1;\n    }\n}\nbody.header-10 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #eee;\n    }\n    #BackgroundImage.has-bg-image-loaded,\n    blockquote.main-quote {\n        opacity: 0.9 !important;\n    }\n    #header {\n        zoom: 0.9;\n    }\n}\nbody.header-20 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #ddd;\n    }\n    #BackgroundImage.has-bg-image-loaded,\n    blockquote.main-quote {\n        opacity: 0.8 !important;\n    }\n    #header {\n        zoom: 0.8;\n    }\n}\nbody.header-30 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #ccc;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.7 !important;\n    }\n    #header {\n        zoom: 0.7;\n    }\n}\nbody.header-40 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #bbb;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.6 !important;\n    }\n    #header {\n        zoom: 0.6;\n    }\n}\nbody.header-50 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #aaa;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.5 !important;\n    }\n    #header {\n        zoom: 0.5;\n    }\n}\nbody.header-60 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #999;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.4 !important;\n    }\n    #header {\n        zoom: 0.4;\n    }\n}\nbody.header-70 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #888;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.3 !important;\n    }\n    #header {\n        zoom: 0.3;\n    }\n}\nbody.header-80 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #777;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.2 !important;\n    }\n    #header {\n        zoom: 0.2;\n    }\n}\nbody.header-90 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #666;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0.1 !important;\n    }\n    #header {\n        zoom: 0.1;\n    }\n}\nbody.header-100 {\n    &.theme-rocket #main #content-below-quote * {\n        color: #555;\n    }\n    #BackgroundImage,\n    blockquote.main-quote {\n        opacity: 0 !important;\n    }\n    #header {\n        zoom: 1;\n        display: none;\n    }\n}\n\nbody.footer-0 {\n    #BackgroundImage,\n    footer {\n        opacity: 1 !important;\n    }\n}\nbody.footer-10 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.9 !important;\n    }\n}\nbody.footer-20 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.8 !important;\n    }\n}\nbody.footer-30 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.7 !important;\n    }\n}\nbody.footer-40 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.6 !important;\n    }\n}\nbody.footer-50 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.5 !important;\n    }\n}\nbody.footer-60 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.4 !important;\n    }\n}\nbody.footer-70 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.3 !important;\n    }\n}\nbody.footer-80 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.2 !important;\n    }\n}\nbody.header-90 {\n    #BackgroundImage,\n    footer {\n        opacity: 0.1 !important;\n    }\n}\nbody.footer-100 {\n    #BackgroundImage,\n    footer {\n        opacity: 0 !important;\n    }\n}\n",".body-loaded * {\n    transition-property:\n        width,\n        min-width,\n        color,\n        background-color,\n        opacity,\n        height,\n        min-height,\n        min-width,\n        max-height,\n        max-width,\n        left,\n        right,\n        top,\n        bottom,\n        color,\n        border-radius,\n        border,\n        box-shadow,\n        margin;\n    transition-duration: 0.37s;\n    transition-timing-function: ease-out;\n    transition-delay: 0s;\n}\n","\nbody.mouse-over-logo.no-touch {\n    #BackgroundImage {\n        animation-duration: 0.3s; /* the duration of the animation */\n        animation-timing-function: ease-out; /* how the animation will behave */\n        animation-delay: 0s; /* how long to delay the animation from starting */\n        animation-iteration-count: 1; /* how many times the animation will play */\n        animation-name: showImage; /* the name of the animation we defined above */\n        animation-fill-mode: forwards;\n        display: block!important;\n        background-size: cover;\n        @keyframes showImage {\n            0% {\n                opacity: 0;\n                position: fixed;\n                top: 0;\n                bottom: 0;\n                right: 0;\n                left: 0;\n                z-index: 999;\n            }\n            100% {\n                display: block!important;\n                opacity: 1;\n                position: fixed;\n                top: 0;\n                bottom: 0;\n                right: 0;\n                left: 0;\n                z-index: 999;\n\n            }\n\n        }\n    }\n    #logo {\n        z-index: 99999999999!important;\n    }\n}\n\nbody.mouse-over-logo {\n    #header {\n        .logo-header {\n            position: relative;\n            z-index: 9999999999;\n        }\n        .bread-crumb {\n            display: none;\n        }\n    }\n}\n","// //** see blockquote **/\n@keyframes colorChange {\n    0% {\n        color: $colour_blue_cobalter;\n    }\n    92% {\n        color: $colour_blue_cobalter;\n    }\n    93% {\n        color: $colour_blue_cobalter;\n    }\n    94% {\n        color: $colour_sunny_side_up_yellow;\n    }\n    95% {\n        color: $colour_blue_cobalter;\n    }\n    96% {\n        color: $colour_sunny_side_up_yellow;\n    }\n    97% {\n        color: $colour_blue_cobalter;\n    }\n    98% {\n        color: $colour_sunny_side_up_yellow;\n    }\n    99% {\n        color: $colour_blue_cobalter;\n    }\n    100% {\n        color: $colour_blue_cobalter;\n    }\n}\n\nbody.theme-sun #content-below-quote h2 {\n    animation-name: colorChange;\n    animation-duration: 10s; /* Adjust time as needed */\n    animation-iteration-count: 1; /* Runs only once */\n}\n",".image-container {\n    perspective: 1000px;\n    transform-style: preserve-3d;\n}\n\n.image-container img {\n    transition: transform 0.6s ease-out;\n    transform: scale(1);\n}\n\n.image-container:hover img {\n    transform: scale(1.2) rotateY(calc(var(--mouse-x) * 1deg)) rotateX(calc(var(--mouse-y) * -1deg));\n    z-index: 9999999999;\n    position: relative;\n}\n",".arrow-down {\n    rotate: 105deg;\n    transform-origin: center; /* change to e.g. \"top center\" for a pendulum effect */\n    animation: swing 2.3s ease-in-out infinite alternate;\n    animation-delay: 1s;\n}\n\n@keyframes swing {\n    from {\n        rotate: 105deg;\n    }\n    to {\n        rotate: 75deg;\n    }\n}\n\n/* Respect users who prefer less motion */\n@media (prefers-reduced-motion: reduce) {\n    .arrow-down {\n        animation: none;\n        rotate: 90deg;\n    }\n}\n","@page {\n    width: 210mm;\n    height: 297mm;\n    margin-top: 20mm !important;\n    margin-right: 0 !important;\n    margin-left: 0 !important;\n    overflow: visible !important;\n    margin-bottom: auto !important;\n    orientation: portrait;\n    // padding-bottom: 4rem!important;\n}\n@page:first {\n    margin-top: 0mm !important;\n}\n@media print {\n    body,\n    html {\n        overflow: visible !important;\n        margin-bottom: auto !important;\n        font-size: 5px !important;\n        background-color: #fff;\n        *,\n        *:before {\n            color: $colour_black_rock_n_roll !important;\n        }\n\n        header#print {\n            box-shadow: inset 0 0 0 1000px $colour_light_grey_aotrom;\n            display: block !important;\n            top: 0;\n            left: 0;\n            right: 0;\n            img {\n                display: block;\n                width: 100px;\n                margin-right: 5rem;\n                margin-top: -20px;\n                float: right;\n            }\n            h1 {\n                text-align: center;\n                clear: right;\n                font-size: 5rem;\n                text-transform: uppercase;\n                font-weight: 500;\n                font-family: $base_font_headers;\n                color: $colour_blue_cobalter_highlights !important;\n                padding-bottom: 2rem;\n            }\n        }\n        #SiblingsAndChildren,\n        // blockquote,\n        #nav,\n        footer,\n        iframe,\n        embed,\n        #header,\n        #BackgroundVideo,\n        span .open,\n        span .closed,\n        form,\n        .edit-me-button {\n            display: none !important;\n        }\n        main#main {\n            max-width: 70%;\n            margin-left: auto;\n            margin-right: auto;\n            margin-bottom: auto !important;\n            overflow: visible !important;\n            padding: 1rem 12rem 0 12rem !important;\n            * {\n                overflow: visible !important;\n            }\n            &:before {\n                display: block;\n                background-image: url(./images/SSU_Logo_horizontal_.png) !important;\n                background-position: top left;\n                background-size: contain;\n                height: 100px;\n                width: 100%;\n            }\n\n            p {\n                padding-bottom: 2rem;\n            }\n            h1 {\n                font-size: 5rem;\n            }\n            h2 {\n                font-size: 2.5rem;\n            }\n            h1,\n            h2 {\n                margin-top: 2rem !important;\n                padding-left: 0px !important;\n                padding-bottom: 0 !important;\n                margin-bottom: 1rem !important;\n            }\n            h3 {\n                font-size: 2rem;\n            }\n            h1,\n            h2,\n            h3,\n            h4,\n            h5,\n            h6 {\n                page-break-before: auto;\n                page-break-inside: avoid;\n                page-break-after: avoid;\n                &:before,\n                &:after {\n                    display: none;\n                }\n            }\n            p,\n            li,\n            address {\n                font-size: 2rem;\n            }\n            ul,\n            ol,\n            li,\n            p {\n                padding-top: 0 !important;\n                padding-bottom: 0 !important;\n                margin-top: 0 !important;\n                margin-bottom: 0 !important;\n            }\n            li,\n            p {\n                padding-top: 5px !important;\n                padding-bottom: 5px !important;\n            }\n            table {\n                page-break-inside: avoid;\n                th,\n                td {\n                    border: 1px solid $colour_black_rock_n_roll !important;\n                }\n            }\n            pre {\n                white-space: pre-wrap;\n                color: $colour_black_rock_n_roll;\n            }\n            a {\n                text-decoration-color: $colour_blue_cobalter_highlights !important;\n                &:after {\n                    content: \" (\" attr(href) \") \";\n                    font-size: 10px;\n                    word-break: break-all;\n                }\n            }\n            .last-updated {\n                margin-top: 5rem !important;\n                display: block !important;\n                opacity: 1 !important;\n                color: #000 !important;\n                text-align: left !important;\n            }\n        }\n    }\n}\n"],"names":[],"sourceRoot":""}
