ge-hover\";\n@import \"scss/animations/arrow-down\";\n\n@import \"scss/print/print\";\n","//to do!\nbody main#main {\n    animation-duration: 0.3s; /* the duration of the animation */\n    animation-timing-function: ease-out; /* how the animation will behave */\n    animation-delay: 0s; /* how long to delay the animation from starting */\n    animation-iteration-count: 1; /* how many times the animation will play */\n    animation-name: loadTransition; /* the name of the animation we defined above */\n    animation-fill-mode: forwards;\n    opacity: 0;\n    @keyframes loadTransition {\n        0% {\n            opacity: 0;\n        }\n        100% {\n            opacity: 1;\n        }\n    }\n}\n\nbody.body-unloaded main#main {\n    animation-duration: 1s; /* the duration of the animation */\n    animation-timing-function: ease-out; /* how the animation will behave */\n    animation-delay: 0s; /* how long to delay the animation from starting */\n    animation-iteration-count: 1; /* how many times the animation will play */\n    animation-name: unloadTransition; /* the name of the animation we defined above */\n    animation-fill-mode: forwards;\n    opacity: 1;\n    @keyframes unloadTransition {\n        0% {\n            opacity: 1;\n        }\n        100% {\n            opacity: 0;\n        }\n    }\n}\n","/**\n * Example usage:\n * .asymmetric-card {\n *   @include sketch-border(6px, 2px, 5px, 1px, #3b82f6);\n * }\n * .action-button {\n *   @include sketch-border(4px, #10b981);\n * }\n * .top-bottom-frame {\n *   @include sketch-border(5px 0 3px 0, #6366f1);\n * }\n * .heading-underline {\n *   @include sketch-border($top: 0, $right: 0, $bottom: 4px, $left: 0, $color: #f59e0b);\n * }\n */\n\n@mixin sketch-border(\n  $top: 5px,\n  $right: $top,\n  $bottom: $top,\n  $left: $right,\n  $color: #475569\n) {\n  // If a color is passed as the 2nd argument (e.g. 4px, #3b82f6)\n  @if type-of($right) == 'color' {\n    $color: $right;\n    $right: $top;\n    $bottom: $top;\n    $left: $top;\n  }\n\n  border-style: solid;\n  border-color: $color;\n\n  // If a shorthand list is passed (e.g. 5px 0 3px 0, #3b82f6)\n  @if length($top) > 1 {\n    border-width: $top;\n  } @else {\n    border-top-width: $top;\n    border-right-width: $right;\n    border-bottom-width: $bottom;\n    border-left-width: $left;\n  }\n\n  border-radius: 8px 12px 10px 6px;\n  filter: url('#smooth-sketch');\n}\n","* {\n    color: $colour_outer_space_love;\n    scroll-behavior: smooth;\n}\na {\n    color: $colour_outer_space_love;\n    &:link {\n        color: $colour_outer_space_love;\n    }\n    &:visited {\n        color: $colour_outer_space_love;\n    }\n}\n//all items in main with id set scroll-margin-top higher\nmain *[id] {\n    scroll-margin-top: 10rem;\n}\n","// ===============================\n// Main ones\n// ===============================\n$colour_sunny_side_up_yellow: #f7cd55;\n\n// ===============================\n// Greys, black, white, transparent, gradients\n// ===============================\n$colour-white: #fff;\n$colour_black: #000;\n$colour_white_ten_percent: #ffffff22;\n\n$colour_boot_black: #040403;\n$colour_boot_black_semi: #040403cc;\n$colour_black_lighter: #111;\n$colour_almost_black_dreamless_sleep: #111;\n\n$colour_darker_grey_catch_22: #222;\n$colour_outer_space_love: #333;\n$colour_black_rock_n_roll: #191919;\n\n$colour_lucky_grey: #777777;\n$colour_yep_thats_grey: #575757;\n$colour_yep_thats_grey_light: #55555500;\n$colour_yep_thats_grey_semi: #575757cc;\n$colour_yep_thats_grey_revers: #959595;\n\n$colour_light_grey_gravel_fint: #bbb;\n$colour_screaming_grey: #aaa;\n$colour_modern_iron: #a7a7a7;\n$colour_modern_iron_half: #a7a7a777;\n\n$colour_light_grey_aotrom: #e6e6e6;\n$colour_light_grey_aotrom_fifty_percent: #e6e6e677;\n\n$colour_overcast_sunny_side_up: #c3bfb3;\n\n$colour_transparent: transparent;\n\n$colour_grey_white_grey: linear-gradient(270deg, $colour_light_grey_aotrom, $colour_white, $colour_light_grey_aotrom);\n\n// ===============================\n// Yellows\n// ===============================\n$colour_sunny_side_up_yellow_less: #f7cd55cc;\n$colour_sunny_side_up_yellow_ten_percent: #f7cd5522;\n$colour_hypocrite_yellow: #f7cd55;\n$colour_hypocrite_yellow_lighter: #c6b380;\n\n$colour_yellow: yellow;\n$colour_burned_sunny_side_up: #e4b105;\n$colour_burned_sunny_side_up_thirty_percent: #e4b10533;\n$colour_organic_egg_yolk: #e4b105;\n\n// ===============================\n// Greens\n// ===============================\n$colour_sunny_side_up_green: #00ab06;\n$colour_sunny_side_up_green_darker: #0f3d11;\n\n$colour_painty_green: #386548;\n$colour_on_the_fence_green: #81ce86;\n$colour_on_the_fence_green_transparent: #81ce86;\n\n$colour_burngreen: #94c93d;\n$colour_burngreen: #a6bd7f;\n\n$colour_ekos_green: #95c93d;\n$colour_ekos_green: #95c93d;\n\n$colour_green: green;\n\n// ===============================\n// Blues / navies\n// ===============================\n\n$colour_purple_spirituality_in_the_sun: #022866;\n$colour_blue_cobalter_highlights: #022866;\n$colour_blue_cobalter: #022866;\n$colour_blue_cobalter_half: #02286655;\n$colour_blue_cobalter_half_non_transparent: #b9c7ff;\n$colour_blue_cobalter_lighter: #8ca6f9;\n\n$colour_vexy: #0028c9;\n$colour_center_shake_blue: #0032b9;\n$colour_law_firm_report_cover: #0d3a59;\n$colour_sunny_side_up_sky: #c6e3ea;\n\n// ===============================\n// Purples\n// ===============================\n$colour_purple: purple;\n\n$colour_climate_negative: #6a36c2;\n$colour_anthroposofia: #3a075a;\n$colour_sunny_side_up_dark_purple: #200233;\n\n// ===============================\n// Reds / pinks\n// ===============================\n$colour_red: red;\n$colour_pink: pink;\n\n$colour_rose_storm: #ef5d5d;\n$colour_patrick_star_skin_colour: #ff7b7b;\n$colour_cable_car_red: #fc4b15;\n$colour_ranch_style_beans_with_onions: #240000;\n\n// ===============================\n// Oranges\n// ===============================\n$colour_orange: orange;\n\n// ===============================\n// Mint / aqua\n// ===============================\n$colour_minty_just_add_chocolate: #8dfdfa;\n",".row {\n    display: grid;\n    grid-template-columns: 1fr;\n    grid-gap: 2rem;\n}\n.center-align-row {\n    text-align: center;\n    * {\n        text-align: center;\n    }\n}\n","html {\n    margin: 0;\n    padding: 0;\n    background-color: $colour_light_grey_aotrom;\n    font-family: $base_font;\n}\nbody {\n    margin: 0;\n    padding: 0;\n    background-color: $colour_light_grey_aotrom;\n    font-family: $base_font;\n    background-color: $colour_sunny_side_up_yellow;\n}\n#BackgroundImage {\n    transition: none;\n    display: block;\n    background-size: cover;\n    position: fixed;\n    opacity: 0;\n    top: 0;\n    right: 0;\n    left: 0;\n    bottom: 0;\n    iframe {\n        width: 120vw;\n        height: 56.25vw; /* Given a 16:9 aspect ratio, 9/16*100 = 56.25 */\n        min-height: 120vh !important;\n        min-width: 177.77vh !important; /* Given a 16:9 aspect ratio, 16/9*100 = 177.77 */\n        position: absolute;\n        top: 50%;\n        left: 50%;\n        transform: translate(-50%, -50%);\n    }\n}\nmain#main {\n    position: relative;\n    z-index: 2;\n    padding-top: 120vh;\n    padding-bottom: 2rem;\n    #content-below-quote {\n        min-height: 70vh;\n        .element {\n            margin-top: 6rem;\n            clear: both;\n        }\n    }\n}\nfooter#footer {\n    padding: 2rem;\n}\nbody.has-bg-image-loaded {\n    #BackgroundImage {\n        opacity: 1;\n    }\n}\nbody.no-rocket-show.no-quote {\n    #main {\n        padding-top: calc(50vh - 8rem);\n    }\n    #BackgroundImage {\n        display: none;\n    }\n    .main-quote {\n        display: none;\n    }\n}\n","// @import url('https://fonts.googleapis.com/css2?family=Titillium+Web:ital,wght@0,400;0,600;0,700;1,200;1,600;1,700&display=swap');\n// @import url(\"https://fonts.googleapis.com/css2?&family=Nunito+Sans:ital,wght@0,200;0,400;0,700;1,200;1,400;1,700&display=swap\");\n\n$base_font: \"Nunito Sans\", sans-serif;\n$base_font_condensed: \"Nunito Sans\", sans-serif;\n$base_font_headers: \"Oswald\", sans-serif;\n\n// @import url(\"https://use.typekit.net/drk0ynw.css\");\n//\n// $base_font: 'ff-good-web-pro', sans-serif;\n// $base_font_condensed: 'ff-good-web-pro-condensed', sans-serif;\n","footer#footer {\n    background-color: $colour_yep_thats_grey_semi;\n    padding-top: 6vh;\n    padding-right: 6vw;\n    padding-bottom: 6vh;\n    position: relative;\n    z-index: 35;\n    div.col {\n        padding-bottom: 2vh;\n        text-align: center;\n    }\n    p {\n        padding: 0;\n        margin: 0;\n        clear: both;\n        padding-bottom: 1rem;\n        color: $colour_white;\n    }\n    address {\n        padding: 0;\n        padding: 0;\n        margin: 0;\n        margin: 0;\n        clear: both;\n        clear: both;\n        padding-bottom: 1rem;\n        padding-bottom: 1rem;\n    }\n    ul {\n        padding: 0;\n        margin: 0;\n        clear: both;\n        padding-bottom: 1rem;\n        list-style: none;\n    }\n    li {\n        padding: 0;\n        margin: 0;\n        clear: both;\n        padding-bottom: 1rem;\n        list-style: none;\n    }\n    #theme-selectors {\n        padding: 0;\n        margin: 0;\n        clear: both;\n        padding-bottom: 1rem;\n        display: none;\n    }\n    * {\n        font-size: 2rem;\n        color: $colour_white;\n    }\n    a {\n        color: $colour_white;\n        text-decoration: none;\n        &:link {\n            color: $colour_white;\n        }\n        &:visited {\n            color: $colour_white;\n        }\n        &:hover {\n            color: $colour_sunny_side_up_yellow;\n        }\n    }\n    li.current a {\n        color: $colour_sunny_side_up_yellow;\n        font-weight: 600;\n    }\n    li.section a {\n        font-weight: 600;\n    }\n\n    .image-holder {\n        display: block;\n        img {\n            max-width: 100%;\n            width: 200px;\n            display: inline-block;\n            margin: 0;\n        }\n    }\n}\n","#header {\n    position: fixed;\n    z-index: 9999;\n    top: 0;\n    left: 0;\n    right: 0;\n    zoom: 1;\n    img {\n        display: none;\n    }\n    #logo {\n        display: block;\n        background-image: url(./images/logo-small.svg);\n        background-size: contain;\n        position: absolute;\n        top: 0;\n        right: 6vw;\n        z-index: 3;\n    }\n    h1 {\n        font-weight: 500;\n        font-family: $base_font_headers;\n        text-transform: uppercase;\n        line-height: 1;\n        position: relative;\n        color: $colour_blue_cobalter_highlights;\n        * {\n            color: $colour_blue_cobalter_highlights;\n        }\n        position: absolute;\n        text-align: right;\n        z-index: 3;\n        margin-left: 17vw;\n        a {\n            text-decoration: none;\n        }\n        a,\n        span {\n            opacity: 0.7;\n        }\n        a.page-title {\n            opacity: 1;\n        }\n        a.bread-crumb {\n            display: block;\n            padding-top: 0.5rem;\n            font-size: 2rem;\n        }\n    }\n}\nbody.past-header:not(.menu-on) {\n    #header {\n        height: 5rem;\n        z-index: 3;\n        background-color: #fff;\n        position: fixed;\n        border-bottom: 0px solid $colour_yep_thats_grey;\n        box-shadow: 0px 3px 20px -6px rgba(0, 0, 0, 0.5);\n        opacity: 0;\n        #logo {\n            height: 0 !important;\n            width: 0 !important;\n            margin-top: 0;\n            z-index: 0;\n        }\n        h1 {\n            margin-top: 0.67em;\n            margin-left: 0vw;\n            color: $colour_yep_thats_grey;\n            display: block;\n            font-size: 2.5rem;\n            right: 6vw;\n            opacity: 1;\n            top: 0px;\n            * {\n                color: $colour_yep_thats_grey;\n            }\n            .page-title {\n                color: $colour_blue_cobalter_highlights;\n            }\n            .bread-crumb {\n                display: none !important;\n            }\n        }\n        svg {\n            filter: grayscale(100%);\n        }\n    }\n}\nbody.past-header.just-scrolled.scrolled-up {\n    #header {\n        opacity: 1;\n    }\n}\n// body.footer-visible {\n//     #header,\n//     #header * {\n//         height: 0;\n//         overflow: hidden;\n//     }\n// }\n\n@media only screen and (max-width: 1049px) {\n    body.footer-visible {\n        #nav {\n            height: 0;\n        }\n    }\n}\n\n.up-baby-up {\n    transform: rotate(180deg);\n    display: inline-block;\n    margin-right: -0.2em;\n}\n","/**\n * see responsive.css for media queries\n */\n#nav {\n    position: fixed;\n    bottom: 0;\n    right: 0;\n    height: 20rem;\n    width: 20rem;\n    z-index: 25;\n    margin-right: -10rem;\n    margin-bottom: -10rem;\n    background-color: $colour_sunny_side_up_yellow;\n    border-radius: 50%;\n    box-shadow: 0px 3px 20px -6px rgb(0 0 0 / 50%);\n    border: 4px dotted #ffffff;\n    a {\n        text-decoration: none;\n    }\n    * {\n        font-family: $base_font_headers;\n        font-weight: 500;\n        color: $colour_blue_cobalter_highlights;\n    }\n    i {\n        font-style: normal;\n        color: transparent !important;\n        background-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A//www.w3.org/2000/svg'%20viewBox%3D'23.5%2022.5%2031%2029'%3E%3Cpath%20d%3D'M26%2037H50%20M40%2025L52%2037L40%2049'%20fill%3D'none'%20stroke%3D'%23022866'%20stroke-width%3D'5'%20stroke-linecap%3D'round'%20stroke-linejoin%3D'round'/%3E%3C/svg%3E\");\n        background-position: center;\n        background-size: contain;\n        background-repeat: no-repeat;\n        background-size: 60%;\n        width: 1.5em;\n        transform-origin: center;\n        transition: transform 0.3s ease-in-out;\n        &.open {\n            background-position: center 55%;\n            &:hover {\n                transform: rotate(45deg);\n            }\n        }\n        &.closed {\n            transform: rotate(90deg);\n            background-position: 22% center;\n            &:hover {\n                transform: rotate(225deg);\n            }\n        }\n    }\n\n    #menu-toggle {\n        transform: rotate(225deg);\n        height: 5rem;\n        width: 5rem;\n        line-height: 5rem; //required to center;\n        position: absolute;\n        left: 3.5rem;\n        top: 3.5rem;\n        z-index: 9;\n        display: table-cell;\n        text-align: left;\n        vertical-align: middle;\n        text-decoration: none;\n        outline: 0;\n        cursor: pointer;\n        svg {\n            height: 5rem;\n            width: auto;\n            vertical-align: middle;\n        }\n    }\n\n    #nav-inner {\n        width: 0;\n        height: 0;\n        position: absolute;\n        opacity: 0;\n        nav {\n            display: none;\n        }\n    }\n    .menu-button {\n        display: inline-block;\n        opacity: 1;\n        color: #fff;\n        font-size: 5rem;\n        transform: rotateY(180deg);\n        transition: 0.5s transform;\n    }\n    .icon {\n        left: -5rem;\n        top: 0;\n    }\n}\nbody.show-logo {\n    #header {\n        transition: all 0 ease-in-out!important;\n        transition: zoom 0.4s ease-in-out;\n        display: block !important;\n        zoom: 1 !important;\n        position: fixed !important;\n        opacity: 1 !important;\n        z-index: 99999;\n        height: 0 !important;\n        border: none !important;\n        h1 {\n            display: none!important;\n        }\n        .bread-crumb {\n            display: none!important;\n        }\n    }\n}\nbody.menu-on {\n    #nav {\n        background-color: $colour_sunny_side_up_yellow;\n        opacity: 1;\n        height: 100vh;\n        width: 100vw;\n        border-radius: 0;\n        margin-left: 0;\n        margin-bottom: 0;\n        right: 0;\n        left: auto;\n        bottom: 0;\n        margin-right: 0;\n        border: none!important;\n        #menu-toggle {\n            opacity: 1;\n            bottom: 2rem;\n            right: 2rem;\n            top: auto;\n            left: auto;\n        }\n\n        #nav-inner {\n            opacity: 1 !important;\n            height: auto !important;\n            width: auto !important;\n            left: 10%;\n            top: 50%;\n            transform: translate(0, -50%);\n            vertical-align: middle;\n            margin: 0;\n            padding: 0 0 0 6rem;\n            overflow: hidden;\n            nav {\n                display: block;\n            }\n            // display: flex;\n            // justify-content: center;\n            // align-items: center;\n            ul {\n                padding-left: 0;\n                margin-left: 0;\n                list-style: none;\n                text-transform: uppercase;\n                li {\n                    transition: all 0.3s ease-in-out;\n                    padding-left: 0;\n                    margin-left: 0;\n                    margin-bottom: 5vh;\n                    margin-top: 5vh;\n                    font-size: calc(2rem + 1vh);\n                    list-style: none;\n                    text-transform: uppercase;\n                    padding-top: 0;\n                    padding-bottom: 0;\n                    a {\n                        border-bottom: 3px solid transparent;\n                        &:hover {\n                            border-bottom: 3px solid $colour_blue_cobalter_highlights;\n                        }\n                    }\n                    ul {\n                        li {\n                            font-size: calc(1rem + 1vh);\n                            margin-bottom: 1vh;\n                            margin-top: 1vh;\n                            i {\n                                background-size: 70%;\n                            }\n                            ul {\n                                li {\n                                    font-size: calc(1rem + 1vh);\n                                    i {\n                                        background-size: 80%;\n                                    }\n                                }\n                            }\n                        }\n                    }\n                }\n                li.current {\n                    > a {\n                        border-bottom: 3px solid $colour_blue_cobalter_highlights;\n                    }\n                }\n                li.section {\n                    > a {\n                        // text-decoration: underline;\n                        // text-decoration-style: dashed;\n                    }\n                }\n            }\n        }\n        .menu-button {\n            transform: rotateY(0deg);\n        }\n    }\n\n    @media only screen and (max-width: 1049px) {\n        #nav {\n            z-index: 999;\n        }\n    }\n    .collapsibleListHasOpen {\n        > li.collapsibleListNotOpen {\n            font-size: 2rem !important;\n            margin-top: 1vh !important;\n            margin-bottom: 1vh !important;\n            opacity: 0.6 !important;\n        }\n        > li.collapsibleListOpen {\n            display: list-item;\n        }\n    }\n    li.current {\n        > a {\n            border-bottom: 3px solid $colour_blue_cobalter_highlights !important;\n        }\n    }\n}\n\nbody.past-header.menu-on {\n}\nbody.no-touch {\n    #nav {\n        #menu-toggle {\n            svg {\n                opacity: 0.9;\n            }\n            &:hover {\n                svg {\n                    opacity: 1;\n                }\n            }\n        }\n    }\n}\n\nbody.past-header {\n    #nav {\n        opacity: 0.5;\n        &:hover {\n            opacity: 1;\n        }\n    }\n    &.menu-on {\n        #nav {\n            opacity: 1;\n        }\n    }\n}\n\nbody.past-header.scrolled-up {\n    #nav {\n        opacity: 0.75;\n        &:hover {\n            opacity: 1;\n        }\n    }\n    &.menu-on {\n        #nav {\n            opacity: 1;\n        }\n    }\n}\n\nbody.past-header.scrolled-up.just-scrolled {\n    #nav {\n        opacity: 1;\n    }\n}\n\n@media only screen and (min-height: 750px) {\n    body.menu-on {\n        #nav {\n            #nav-inner {\n                ul {\n                    li {\n                        font-size: calc(2rem + 2vh);\n                        ul {\n                            li {\n                                font-size: calc(1rem + 2vh);\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n\n// body.scrolled-down:not(.menu-on) {\n//     @media only screen and (max-width: 1049px) {\n//         #nav,\n//         #menu-toggle {\n//             height: 0!important;\n//             padding: 0!important;\n//             margin-top: 20px!important;\n//             bottom: 0;\n//         }\n//         #menu-toggle {\n//             svg {\n//                 height: 0!important;\n//             }\n//         }\n//     }\n// }\n",".typography {\n    // *, a:link, a:visited {\n    //     color: $colour_vexy;\n    // }\n    p,\n    ul,\n    ol,\n    address {\n        margin-top: 0;\n        padding-top: 0;\n        padding-bottom: 3rem;\n        margin-bottom: 0;\n        line-height: 1.5;\n        font-size: 2.3rem;\n        font-weight: 300;\n        &:last-child {\n            padding-bottom: 2rem;\n        }\n    }\n\n    h1,\n    h2,\n    h3,\n    h4,\n    h5,\n    h6 {\n        font-family: $base_font_headers;\n        font-weight: 500;\n        line-height: 1.5;\n        strong {\n            font-weight: 500;\n        }\n    }\n    h1,\n    h2 {\n        margin-top: 1.5em;\n        padding-bottom: 0.5rem;\n        // font-variant-caps: small-caps;\n        text-transform: uppercase;\n        color: $colour_blue_cobalter;\n        * {\n            color: $colour_blue_cobalter;\n        }\n        border-bottom: 4px dotted $colour_blue_cobalter;\n        &:before {\n            position: absolute;\n            height: 2rem;\n            width: auto;\n            left: 0;\n            right: 0;\n            display: block;\n            content: \" \";\n            margin-top: -2rem;\n        }\n    }\n    h1 {\n        line-height: 1.29;\n        font-size: 4rem;\n    }\n    h2 {\n        font-size: 3.3rem;\n        line-height: 1.3;\n        letter-spacing: -1px;\n    }\n    h3 {\n        font-size: 2.7rem;\n        margin-bottom: 2rem;\n        color: $colour_blue_cobalter;\n        * {\n            color: $colour_blue_cobalter;\n        }\n    }\n    h4 {\n        font-size: 2.3em;\n        margin-bottom: 1rem;\n    }\n    h5 {\n        font-size: 2.3rem;\n        margin-bottom: 1rem;\n    }\n    h6 {\n        font-size: 2.3rem;\n        margin-bottom: 1rem;\n        font-style: italic;\n        font-weight: 200;\n        font-family: $base_font_condensed;\n    }\n    p + ul,\n    p + ol,\n    p + p,\n    ul + p,\n    ol + p {\n        margin-top: -1.7rem !important;\n    }\n    p + ul,\n    p + ol {\n        margin-top: -1.5rem !important;\n    }\n\n    ul,\n    ol {\n        margin-top: 0px;\n        margin-bottom: 0;\n        padding-left: 0;\n        li {\n            line-height: 1.5;\n            margin-left: 2.2rem;\n            margin-bottom: 1rem;\n            padding-left: 0;\n            &::marker {\n                color: $colour_blue_cobalter;\n            }\n            p {\n                margin: 0 !important;\n                padding: 0 !important;\n            }\n            ul,\n            ol {\n                padding-top: 1.7rem;\n                margin-left: 0 !important;\n                padding-left: 2.3rem;\n                padding-bottom: 0;\n                li {\n                    margin-left: 0rem;\n                    padding-left: 0;\n                }\n            }\n        }\n    }\n    .image-container {\n        border: none !important;\n        img {\n            display: block;\n            width: auto !important;\n            height: auto !important;\n            margin: 0 auto;\n            border: 4px dotted $colour_modern_iron;\n            border-radius: 2rem;\n        }\n    }\n    .captionImage {\n        width: auto !important;\n    }\n    p.caption {\n        font-style: italic;\n        font-size: 2rem;\n        width: 100%;\n        text-align: left;\n        margin-left: 0;\n        margin-top: -3rem;\n        text-align: center;\n        line-height: 1.2;\n    }\n\n    .media,\n    .image-container,\n    #content-below-quote blockquote p {\n        display: block;\n        padding: 2rem 0!important;\n        margin: 2rem auto !important;\n        // background: $colour_grey_white_grey;\n        box-sizing: border-box;\n        width: 100%;\n        text-align: left;\n    }\n    #content-below-quote blockquote p {\n        display: block;\n        font-size: calc(2.3rem * 1.6);\n        border-left: 4px dotted $colour_modern_iron!important;\n        padding-left: 2rem !important;\n        line-height: 1.3;\n    }\n    #content-below-quote p + blockquote {\n        p {\n            margin-top: 0!important;\n        }\n    }\n    iframe {\n        margin: 0 auto;\n        display: block;\n        max-width: 100% !important;\n    }\n    .media:after,\n    iframe:after {\n        content: \"\";\n        display: table;\n        clear: both;\n    }\n\n\n    i,\n    em,\n    blockquote,\n    blockquote p {\n        font-weight: 200;\n        font-style: italic;\n        font-family: $base_font_condensed;\n    }\n    a {\n        transition: 0.3s;\n        text-decoration: underline;\n        text-decoration-thickness: 4px;\n        text-decoration-style: solid;\n        // text-decoration-skip-ink: none;\n        text-decoration-color: $colour_blue_cobalter_half!important;\n        &:hover {\n            filter: drop-shadow(0 0 12px $colour_sunny_side_up_yellow);\n            // border-bottom: 3px solid $colour_blue_cobalter;\n            text-decoration-color: $colour_sunny_side_up_yellow!important;\n        }\n        &:active {\n            -webkit-text-stroke-width: 1px;\n            -webkit-text-stroke-color: inherit;\n            text-decoration-color: $colour_blue_cobalter!important;\n        }\n        &:visited {\n            color: $colour_outer_space_love;\n        }\n    }\n    table {\n        width: 100% !important;\n        height: auto !important;\n        clear: both;\n        margin-top: 2rem;\n        margin-bottom: 2rem;\n        border-collapse: collapse;\n        border: 2px dotted $colour_blue_cobalter_highlights;\n        table-layout: fixed;\n        tbody > tr > *:nth-last-child(2) ~ * {\n            width: 50% !important;\n        }\n        tbody > tr > *:nth-last-child(3) ~ * {\n            width: 33.3% !important;\n        }\n        tbody > tr > *:nth-last-child(4) ~ * {\n            width: 25% !important;\n        }\n        tbody > tr > *:nth-last-child(5) ~ * {\n            width: 20% !important;\n        }\n        * {\n            font-size: 1.3rem;\n            line-height: 1.3;\n        }\n        th,\n        td {\n            padding: 0.7rem;\n            border: 2px dotted $colour_blue_cobalter_highlights;\n            width: auto !important;\n            * {\n                margin: 0 !important;\n                padding: 0 !important;\n            }\n            li {\n                list-style: none;\n                &:before {\n                    content: \"- \";\n                }\n            }\n            li,\n            p {\n                padding-bottom: 1.3rem;\n            }\n        }\n        th {\n            background-color: $colour_blue_cobalter_highlights;\n            color: $colour_white;\n            border: 2px dotted $colour_white !important;\n        }\n        th[scope=\"col\"] {\n            vertical-align: bottom;\n        }\n        th[scope=\"row\"] {\n            text-align: left;\n        }\n        td {\n            vertical-align: top;\n        }\n    }\n    hr {\n        height: 0;\n        border-top: 4px dotted $colour_blue_cobalter_half_non_transparent;\n        border-bottom: none;\n    }\n    pre {\n        width: 100%;\n        overflow-x: auto;\n        font-size: 10px;\n        font-family: monospace;\n        background-color: $colour_darker_grey_catch_22;\n        padding: 1rem 10px;\n        border-top-right-radius: 1rem;\n        color: $colour_hypocrite_yellow;\n    }\n    strong,\n    b {\n        font-weight: 600;\n        color: $colour_blue_cobalter;\n    }\n\n    .last-updated {\n        font-weight: 200;\n        color: #000 !important;\n        font-style: italic;\n        font-size: 1.5rem;\n        text-align: center;\n        background-color: $colour_sunny_side_up_yellow;\n        width: fit-content;\n        padding: 0.5rem 1rem !important;\n        margin: 80vh auto 0 auto !important;\n        border-radius: 2rem;\n    }\n}\n","$colour_bad: red;\n$colour_good: green;\n$background_color_1: #f8f8f8;\n$background_color_2: #ffcc1a;\n$background_color_5: none;\n$background_color_6: transparent;\n\n.typography {\n    form {\n        width: auto !important;\n        * {\n            font-size: 2rem;\n        }\n        margin-top: 2rem;\n        margin-bottom: 2rem;\n        fieldset,\n        .userform-fields {\n            border: 2px dotted $colour_modern_iron !important;\n            border-top-right-radius: 1rem;\n            padding: 3rem 3vw;\n            background-color: $colour_white;\n            margin: 2rem 0;\n            h1,\n            h2,\n            h3,\n            h4,\n            h5,\n            h6 {\n                font-size: 2rem;\n                text-transform: uppercase;\n                font-weight: bold;\n                &:before {\n                    border: none !important;\n                }\n            }\n            h1,\n            h2,\n            h3,\n            h4,\n            h5,\n            h6,\n            p,\n            ul,\n            ol {\n                padding-top: 1rem;\n                padding-bottom: 0em;\n                margin: 0;\n                float: none;\n                line-height: 1.2;\n            }\n            .field {\n                padding-top: 1rem;\n                width: 100%;\n                padding-bottom: 1rem;\n            }\n            label {\n                font-size: 2rem;\n                // font-style: italic;\n                color: $colour_yep_thats_grey !important;\n            }\n            .middleColumn {\n                display: block;\n                text-align: left;\n                input,\n                textarea,\n                select {\n                    background-color: $colour_light_grey_aotrom;\n                    width: calc(100% - 3rem);\n                    border: none;\n                    margin-top: 0px;\n                    padding: 1.5rem;\n                    font-weight: 600;\n                    border-bottom: 4px dotted $colour_modern_iron;\n                    color: $colour_black_lighter;\n                    &:focus {\n                        border-bottom: 3px solid $colour_burngreen;\n                        outline: none !important;\n                        background-color: $colour_burngreen;\n                    }\n                    border-top-right-radius: 1rem;\n                    &.no-value {\n                        border-bottom-color: $colour_blue_cobalter !important;\n                    }\n                    &.no-value:focus {\n                        border-bottom: 3px solid $colour_sunny_side_up_yellow !important;\n                    }\n                }\n\n                select {\n                    width: 100%;\n                }\n                & + label.right {\n                    display: block;\n                    text-align: left;\n                    font-style: italic;\n                }\n                ul {\n                    margin-left: 0 !important;\n                    padding-left: 0 !important;\n                    margin-top: 0px;\n                    padding-top: 0px;\n                }\n                li {\n                    &:nth-child(odd) {\n                        margin-right: 3rem !important;\n                    }\n                    list-style: none !important;\n                    margin-top: 0px;\n                    padding-top: 0px;\n                    padding-bottom: 0.5rem;\n                }\n                .radio,\n                .checkbox {\n                    border: 0;\n                    &:hover {\n                        border: 0;\n                    }\n                    &:focus {\n                        border: 0;\n                    }\n                }\n            }\n            p.checkbox {\n                display: block;\n                text-align: left;\n            }\n            .fieldgroup {\n                .middleColumn {\n                    margin-left: 0px;\n                }\n            }\n            label {\n                padding-bottom: 0.2rem;\n                display: block;\n            }\n            label.FormHeading {\n                display: block;\n                color: $colour_vexy;\n                font-weight: 600;\n                margin-bottom: 1rem;\n            }\n            span.message {\n                margin-top: 0;\n                font-weight: 900px;\n            }\n            span.bad {\n                background-color: $colour_bad;\n                color: $colour_white;\n            }\n            span.required {\n                background-color: $colour_bad;\n                color: $colour_white;\n            }\n            span.good {\n                background-color: $colour_good;\n                color: $colour_white;\n            }\n            .field + span.message {\n                margin-top: -0.8rem;\n            }\n\n            input.password,\n            input.numeric,\n            input.currency,\n            input.date {\n                max-width: 27rem;\n            }\n            .optionset,\n            .checkboxset {\n                label.left {\n                    border: 0;\n                }\n            }\n            .radio {\n                width: auto !important;\n            }\n            .checkbox {\n                width: auto !important;\n                label.right {\n                    display: block;\n                    margin-left: 0px;\n                    text-align: left;\n                    line-height: 1;\n                }\n                input {\n                    float: left;\n                    margin-top: 13px;\n                    margin-left: 13px;\n                }\n            }\n            .confirmedpassword {\n                .middleColumn {\n                    margin-left: 0px;\n                    a {\n                        display: block;\n                    }\n                }\n            }\n            span.readonly {\n                padding: 0.7rem;\n                margin-top: 0px;\n                color: $colour_black;\n                font-weight: 600;\n                border-bottom: 3px solid $colour_vexy !important;\n                display: block;\n                background-color: $colour_light_grey_aotrom;\n                border-top-right-radius: 1rem;\n                font-size: 2rem;\n            }\n        }\n        .btn-toolbar {\n            padding: 0;\n            display: block;\n            text-align: right;\n            input {\n                padding: 1.3rem 1.7rem;\n                background: $colour_blue_cobalter;\n                border-top-right-radius: 0;\n                border-bottom-left-radius: 1rem;\n                border: 2px dotted $colour_modern_iron;\n                text-decoration: none !important;\n                width: auto;\n                text-align: center;\n                font-weight: 600;\n                color: $colour_white;\n                &:hover {\n                    margin-top: -1px;\n                    margin-bottom: 1px;\n                }\n                &:active {\n                    color: $colour_black;\n                    background: $colour_hypocrite_yellow;\n                }\n            }\n        }\n        p {\n            margin-top: 1.7rem !important;\n            margin-left: 0 !important;\n            font-size: 2rem !important;\n        }\n        p.ForgotPassword {\n            display: block;\n            text-align: left;\n        }\n        .message {\n            font-size: 2rem !important;\n            line-height: 1;\n            margin-bottom: 0.5rem;\n            font-weight: 600;\n            background-color: $colour_sunny_side_up_yellow;\n            display: block;\n            padding: 1rem;\n            text-align: center;\n            color: $colour_black_lighter;\n            a {\n                display: inline-block;\n                color: $colour_white;\n                padding: 0 3px;\n            }\n        }\n        > p.message {\n            margin-bottom: -3.5rem !important;\n            width: calc(50% - 2rem);\n            z-index: 9;\n            position: relative;\n            left: 50%;\n        }\n    }\n}\n",".field.checkbox {\n    font-size: 2 !important;\n    * {\n        font-size: 2 !important;\n    }\n    input {\n        display: inline-block;\n        float: inherit !important;\n        position: absolute;\n        & + label {\n            border: none;\n            display: inline-block;\n            position: relative;\n            -webkit-appearance: none;\n            padding-left: 4.5rem;\n            line-height: 1 !important;\n            &:after {\n                content: \"×\";\n                background-color: $colour_light_grey_aotrom;\n                color: brown;\n                width: 4rem;\n                height: 4rem;\n                line-height: 2;\n                text-align: center;\n                position: absolute;\n                top: 0px;\n                left: 0px;\n            }\n        }\n        &:focus + label:after {\n            background-color: $colour_burngreen !important;\n        }\n        &:checked {\n            & + label {\n                &:after {\n                    color: $colour_black;\n                    content: \"✔\";\n                    opacity: 1;\n                }\n            }\n        }\n    }\n    &:hover {\n        input {\n            & + label {\n                &:after {\n                    opacity: 1;\n                    // content: '✔';\n                }\n            }\n        }\n    }\n}\n\n.optionset {\n    font-size: 2 !important;\n    * {\n        font-size: 2 !important;\n    }\n\n    li {\n        padding: 0px !important;\n        margin: 0px !important;\n        margin-bottom: 1rem !important;\n        width: 100%;\n        label {\n            display: inline-block;\n        }\n        input {\n            display: inline-block;\n            float: inherit !important;\n            position: absolute;\n            & + label {\n                position: relative;\n                -webkit-appearance: none;\n                padding-left: 4.5rem;\n                line-height: 1.7 !important;\n                &:after {\n                    content: \"×\";\n                    position: absolute;\n                    background-color: $colour_light_grey_aotrom;\n                    color: brown;\n                    width: 4rem;\n                    height: 4rem;\n                    line-height: 2;\n                    text-align: center;\n                    top: 0px;\n                    left: 0px;\n                }\n            }\n            &:focus + label:after {\n                background-color: $colour_burngreen !important;\n            }\n            &:checked {\n                & + label {\n                    &:after {\n                        color: $colour_black;\n                        content: \"✔\";\n                        opacity: 1;\n                        background-color: $colour_sunny_side_up_yellow;\n                    }\n                }\n            }\n        }\n        input[type=\"radio\"] {\n            display: inline-block;\n            float: inherit !important;\n            position: absolute;\n            & + label {\n                position: relative;\n                -webkit-appearance: none;\n                padding-left: 4.5rem;\n                line-height: 1.7 !important;\n                &:after {\n                    content: \"×\";\n                    position: absolute;\n                    color: brown;\n                    width: 4rem;\n                    height: 4rem;\n                    line-height: 2;\n                    text-align: center;\n                    top: 0px;\n                    left: 0px;\n                    border-radius: 10px;\n                }\n            }\n            &:focus + label:after {\n                background-color: $colour_burngreen !important;\n            }\n            &:checked {\n                & + label {\n                    &:after {\n                        color: $colour_black;\n                        content: \"✔\";\n                        opacity: 1;\n                    }\n                }\n            }\n        }\n        &:hover {\n            input {\n                & + label {\n                    &:after {\n                        opacity: 1;\n                    }\n                }\n            }\n        }\n    }\n}\n","// Styling Cross-Browser Compatible Range Inputs with Sass\n// Github: https://github.com/darlanrod/input-range-sass\n// Author: Darlan Rod https://github.com/darlanrod\n// Version 1.6.0\n// MIT License\n\n@use \"sass:math\";\n@use \"sass:color\";\n\n$track-color: $colour_sunny_side_up_yellow !default;\n$thumb-color: $colour_blue_cobalter !default;\n\n$thumb-radius: 12px !default;\n$thumb-height: 24px !default;\n$thumb-width: 24px !default;\n$thumb-shadow-size: 4px !default;\n$thumb-shadow-blur: 4px !default;\n$thumb-shadow-color: rgba(0, 0, 0, 0.2) !default;\n$thumb-border-width: 2px !default;\n$thumb-border-color: #eceff1 !default;\n\n$track-width: 100% !default;\n$track-height: 8px !default;\n$track-shadow-size: 1px !default;\n$track-shadow-blur: 1px !default;\n$track-shadow-color: rgba(0, 0, 0, 0.2) !default;\n$track-border-width: 0px !default;\n$track-border-color: #cfd8dc !default;\n\n$track-radius: 5px !default;\n$contrast: 5% !default;\n\n$ie-bottom-track-color: color.adjust($track-color, $lightness: -$contrast) !default;\n\n@mixin shadow($shadow-size, $shadow-blur, $shadow-color) {\n    box-shadow:\n        $shadow-size $shadow-size $shadow-blur $shadow-color,\n        0 0 $shadow-size color.adjust($shadow-color, $lightness: 5%);\n}\n\n@mixin track {\n    cursor: default;\n    height: $track-height;\n    transition: all 0.2s ease;\n    width: $track-width;\n}\n\n@mixin thumb {\n    @include shadow($thumb-shadow-size, $thumb-shadow-blur, $thumb-shadow-color);\n    background: $thumb-color;\n    border: $thumb-border-width solid $thumb-border-color;\n    border-radius: $thumb-radius;\n    box-sizing: border-box;\n    cursor: default;\n    height: $thumb-height;\n    width: $thumb-width;\n}\n\n[type=\"range\"] {\n    -webkit-appearance: none;\n    background: transparent !important;\n    border-radius: 0 !important;\n    border: none !important;\n\n    margin: math.div($thumb-height, 2) 0;\n    width: $track-width;\n    &:focus {\n        background: none !important;\n        border: none !important;\n    }\n    &::-moz-focus-outer {\n        border: 0;\n    }\n\n    // &:focus {\n    //     outline: 0;\n\n    //     &::-webkit-slider-runnable-track {\n    //         background: color.adjust($track-color, $lightness: $contrast);\n    //     }\n\n    //     &::-ms-fill-lower {\n    //         background: $track-color;\n    //     }\n\n    //     &::-ms-fill-upper {\n    //         background: color.adjust($track-color, $lightness: $contrast);\n    //     }\n    // }\n\n    &:focus-visible {\n        outline: 2px solid color.adjust($thumb-color, $lightness: 20%);\n        outline-offset: 2px;\n    }\n\n    &::-webkit-slider-runnable-track {\n        @include track;\n        @include shadow($track-shadow-size, $track-shadow-blur, $track-shadow-color);\n        background: $track-color;\n        border: $track-border-width solid $track-border-color;\n        border-radius: $track-radius;\n\n        &:active {\n            background: color.adjust($track-color, $lightness: $contrast);\n        }\n    }\n\n    &::-webkit-slider-thumb {\n        @include thumb;\n        -webkit-appearance: none;\n        margin-top: calc((#{$track-height} - #{$thumb-height}) / 2);\n\n        &:hover {\n            background: color.adjust($thumb-color, $lightness: 10%);\n        }\n    }\n\n    &::-moz-range-track {\n        @include shadow($track-shadow-size, $track-shadow-blur, $track-shadow-color);\n        @include track;\n        background: $track-color;\n        border: $track-border-width solid $track-border-color;\n        border-radius: $track-radius;\n        height: math.div($track-height, 2);\n\n        &:active {\n            background: color.adjust($track-color, $lightness: $contrast);\n        }\n    }\n\n    &::-moz-range-thumb {\n        @include thumb;\n\n        &:hover {\n            background: color.adjust($thumb-color, $lightness: 10%);\n        }\n    }\n\n    &::-ms-track {\n        @include track;\n        background: transparent;\n        border-color: transparent;\n        border-width: math.div($thumb-height, 2) 0;\n        color: transparent;\n    }\n\n    &::-ms-fill-lower {\n        @include shadow($track-shadow-size, $track-shadow-blur, $track-shadow-color);\n        background: $ie-bottom-track-color;\n        border: $track-border-width solid $track-border-color;\n        border-radius: ($track-radius * 2);\n\n        &:active {\n            background: color.adjust($track-color, $lightness: $contrast);\n        }\n    }\n\n    &::-ms-fill-upper {\n        @include shadow($track-shadow-size, $track-shadow-blur, $track-shadow-color);\n        background: $track-color;\n        border: $track-border-width solid $track-border-color;\n        border-radius: ($track-radius * 2);\n\n        &:active {\n            background: color.adjust($track-color, $lightness: $contrast);\n        }\n    }\n\n    &::-ms-thumb {\n        @include thumb;\n        margin-top: math.div($track-height, 4);\n\n        &:hover {\n            background: color.adjust($thumb-color, $lightness: 10%);\n        }\n    }\n\n    &:disabled {\n        opacity: 0.5;\n\n        &::-webkit-slider-thumb,\n        &::-moz-range-thumb,\n        &::-ms-thumb,\n        &::-webkit-slider-runnable-track,\n        &::-ms-fill-lower,\n        &::-ms-fill-upper {\n            cursor: not-allowed;\n        }\n    }\n}\n",".countable-icons span.icon {\n    background-repeat: no-repeat;\n    background-image: url(./../../images/1.svg);\n    background-size: contain;\n    background-position: left;\n    position: absolute;\n    width: 5rem;\n    display: block;\n}\n\n.icon-1 span.icon {\n    background-image: url(./../../images/1.svg);\n}\n.icon-2 span.icon {\n    background-image: url(./../../images/2.svg);\n}\n.icon-3 span.icon {\n    background-image: url(./../../images/3.svg);\n}\n.icon-4 span.icon {\n    background-image: url(./../../images/4.svg);\n}\n.icon-5 span.icon {\n    background-image: url(./../../images/5.svg);\n}\n.icon-6 span.icon {\n    background-image: url(./../../images/6.svg);\n}\n.icon-7 span.icon {\n    background-image: url(./../../images/7.svg);\n}\n.icon-8 span.icon {\n    background-image: url(./../../images/8.svg);\n}\n.icon-9 span.icon {\n    background-image: url(./../../images/9.svg);\n}\n.icon-10 span.icon {\n    background-image: url(./../../images/1.svg);\n}\n.icon-11 span.icon {\n    background-image: url(./../../images/2.svg);\n}\n.icon-12 span.icon {\n    background-image: url(./../../images/3.svg);\n}\n.icon-13 span.icon {\n    background-image: url(./../../images/4.svg);\n}\n.icon-14 span.icon {\n    background-image: url(./../../images/5.svg);\n}\n.icon-15 span.icon {\n    background-image: url(./../../images/6.svg);\n}\n.icon-16 span.icon {\n    background-image: url(./../../images/7.svg);\n}\n.icon-17 span.icon {\n    background-image: url(./../../images/8.svg);\n}\n","#BackgroundVideo {\n    iframe {\n        width: 100%;\n        min-height: 70vh;\n    }\n    width: auto!important;\n    background-color: $colour_white;\n}\n","main#main {\n    blockquote.main-quote {\n        position: absolute;\n        top: 50vh;\n        left: 0;\n        right: 0;\n        transform: translateY(-50%);\n        padding: 0;\n        margin: 0;\n        p {\n            padding-top: 4rem;\n            padding-bottom: 4rem;\n            padding-left: 2rem;\n            padding-right: 2rem;\n            display: block;\n            margin: 0;\n            background-color: transparent;\n            background: transparent;\n            border-color: transparent;\n            font-size: calc(((1vh + 2.5vw)) + 24px);\n            letter-spacing: -0.5px;\n            filter: drop-shadow(0 0 6px $colour_sunny_side_up_yellow);\n            // background: linear-gradient(270deg, #00000000, #fff, #00000000);\n            line-height: 1.3;\n            overflow: hidden;\n            font-weight: 200;\n            font-style: normal;\n            font-family: $base_font_headers;\n            color: $colour_blue_cobalter;\n            * {\n                color: $colour_blue_cobalter;\n            }\n            // &.has-typing-mode {\n            //     // visibility: hidden;\n            // }\n            .shiner {\n                display: inline-block;\n                cursor: help;\n                text-align: right;\n                animation: shine;\n                animation-duration: 4.2s; /* Full cycle: 2.1s of blinking + 2.1s pause */\n                animation-iteration-count: infinite;\n                text-decoration: none !important;\n                font-style: normal;\n                &.italic {\n                    font-style: italic;\n                }\n                &.smaller {\n                    font-size: 70%;\n                }\n                svg {\n                    vertical-align: baseline;\n                    height: 1.2em;\n                    width: 1.2em;\n                    transition: transform 0.1s ease-in-out;\n                    &:hover {\n                        transform: rotate(90deg);\n                    }\n                }\n            }\n            .Typewriter__wrapper,\n            .Typewriter__wrapper * {\n                visibility: visible;\n            }\n        }\n    }\n}\n\n@keyframes shine {\n    0% {\n        filter: drop-shadow(0 0 0px $colour_sunny_side_up_yellow);\n    }\n    30% {\n        filter: drop-shadow(0 0 0px $colour_sunny_side_up_yellow);\n    }\n    50% {\n        filter: drop-shadow(0 0 20px $colour_sunny_side_up_yellow);\n    }\n    70% {\n        filter: drop-shadow(0 0 0px $colour_sunny_side_up_yellow);\n    }\n    100% {\n        filter: drop-shadow(0 0 0px $colour_sunny_side_up_yellow);\n    }\n}\n\nbody.footer-visible {\n    main#main {\n        blockquote.main-quote {\n            display: none !important;\n            // p {\n            //     .blinker {\n            //         &.smaller {\n            //             rotate: 180deg;\n            //         }\n            //     }\n            // }\n        }\n    }\n}\n\nbody.no-rocket-show.past-header {\n    main#main {\n        blockquote.main-quote {\n            opacity: 0 !important;\n        }\n    }\n}\n","#Breadcrumbs {\n    display: none;\n}\n\nbody.past-header {\n    #Breadcrumbs {\n        color: $colour_white;\n        * {\n            color: $colour_white;\n            font-weight: normal;\n            text-decoration: none;\n        }\n    }\n}\n","\nfooter {\n    #theme-selectors {\n        a {\n            text-decoration: none;\n            display: inline-block;\n            margin-right: 2rem;\n            opacity: 0.77;\n            svg {\n                height: 20px !important;\n                width: 20px !important;\n                fill: $colour_white;\n                &:hover {\n                    fill: $colour_sunny_side_up_yellow !important;\n                }\n            }\n        }\n    }\n}\nbody[data-theme=\"theme-sun\"] {\n    #footer #theme-selectors #theme-sun {\n        svg {\n            fill: $colour_sunny_side_up_yellow;\n        }\n    }\n}\n\nbody[data-theme=\"theme-moon\"] {\n    #footer #theme-selectors #theme-moon {\n        svg {\n            fill: $colour_sunny_side_up_yellow;\n        }\n    }\n}\n","li > ul.collapsibleList,\nli > ul.collapsibleList * {\n    transition-property: height, opacity;\n    transition-duration: 0.3s;\n    transition-timing-function: ease-out;\n}\n\nli.collapsibleListClosed > ul.collapsibleList,\nli.collapsibleListClosed > ul.collapsibleList * {\n    height: 0px;\n    opacity: 0;\n    overflow: hidden;\n}\n\n.collapsibleListOpen > ul.collapsibleList,\n.collapsibleListOpen > ul.collapsibleList * {\n    height: auto;\n    opacity: 100;\n}\n\n.collapsibleList {\n    span.open-close i {\n        cursor: pointer;\n        display: inline-block;\n        // color: #fff;\n    }\n    i.open {\n        // vertical-align: sub;\n    }\n    i.closed {\n        margin-left: -0.2em;\n        // transform: rotate(180deg);\n        // opacity: 1!important;\n        vertical-align: sub;\n        // transform: rotate(270deg);\n    }\n    li {\n        position: relative;\n        &.collapsibleListClosed {\n            > span.open-close {\n                i.closed {\n                    display: inline-block;\n                }\n                i.closed {\n                    display: none;\n                }\n            }\n        }\n        &.collapsibleListOpen {\n            > span.open-close {\n                i.open {\n                    display: none;\n                }\n                i.closed {\n                    display: inline-block;\n                }\n            }\n        }\n    }\n}\n","span.icon i {\n    color: transparent !important;\n}\nbody.has-toc {\n    .typography {\n        #content-below-quote {\n            h1,\n            h2 {\n                padding-left: 5.3rem;\n                cursor: pointer;\n                margin-top: 0;\n                > span:first-child {\n                    display: inline-block;\n                    width: 4.5rem;\n                    margin-left: -5.3rem;\n                    i {\n                        color: $colour_yep_thats_grey_semi;\n                    }\n                }\n                > span:last-child {\n                    display: inline-block;\n                    padding-left: 1rem;\n                }\n                span.active-holder {\n                    display: none;\n                }\n                span {\n                    i {\n                        font-family: $base_font_headers;\n                        font-style: normal;\n                        font-weight: 200;\n                    }\n                    i.open {\n                        display: none;\n                    }\n                    i.closed {\n                        display: block;\n                    }\n                    i.active {\n                        display: none;\n                        animation: blinktoc;\n                        animation-duration: 0.8s;\n                        animation-delay: 0s;\n                        animation-iteration-count: infinite;\n                        font-size: 2rem !important;\n                    }\n                }\n                &.toc-active {\n                    .active-holder,\n                    i.active {\n                        display: inline-block;\n                    }\n                    i.open {\n                        display: none;\n                    }\n                }\n            }\n        }\n    }\n}\n\n@keyframes blinktoc {\n    0% {\n    }\n    25%,\n    75% {\n        color: transparent;\n    }\n    100% {\n    }\n}\n\nbody.has-toc.toc-on {\n    .typography {\n        #content-below-quote {\n            .element {\n                padding: 0;\n                margin-top: 3rem !important;\n            }\n            margin-bottom: 75vh;\n            > * {\n                display: none;\n            }\n            .element,\n            .element > div {\n                display: block;\n            }\n            .element > div > * {\n                display: none;\n            }\n            #SiblingsAndChildren {\n                display: block;\n            }\n            #SiblingsAndChildren > * {\n                display: none;\n            }\n            #SiblingsAndChildren h2,\n            #SiblingsAndChildren h1 {\n                display: block;\n                margin-top: 0;\n            }\n            h1,\n            h2 {\n                width: auto !important;\n                display: block !important;\n                &.open-close.icon {\n                    margin-top: -4px;\n                }\n                i.closed {\n                    display: none;\n                }\n                i.open {\n                    display: inline-block;\n                }\n                &.toc-active {\n                    i.open {\n                        display: inline-block;\n                    }\n                    i.closed,\n                    i.active {\n                        display: none;\n                    }\n                }\n            }\n        }\n    }\n    .element {\n        &:first-of-type {\n            h1:before,\n            h2:before {\n                // border-top: 4px dotted transparent !important;\n            }\n        }\n    }\n}\n\n.bottom-space {\n    margin-bottom: 6rem !important;\n}\n\n.toc-on #SiblingsAndChildren {\n    border-top: 1px solid transparent;\n    h2 {\n        &:after {\n            display: block;\n            width: 100%;\n            content: ' ';\n            border-bottom: 4px dotted $colour_modern_iron;\n            position: absolute;\n            clear: both;\n            left: 0;\n            right: 0;\n            margin-top: 2rem;\n        }\n    }\n}\n",".card-holder {\n    display: grid;\n    gap: 3rem;\n    background: #ffffff55;\n    padding: 3rem;\n    border-radius: 2rem;\n    border-top-left-radius: 0;\n    border: 4px dotted $colour_modern_iron;\n    grid-template-columns: repeat(auto-fit, minmax(100%, 1fr));\n    .card {\n        /* Styles for your cards */\n        h4,\n        p,\n        li {\n            padding: 0;\n            margin: 0;\n        }\n        p, li {\n            font-size: 1.8rem !important;\n        }\n    }\n}\n","#battery-saver-div {\n    display: none;\n    position: fixed;\n    z-index: 1000;\n\n    top: 0;\n    left: 0;\n    bottom: 0;\n    right: 0;\n\n    background-color: black;\n\n    text-align: center;\n\n    flex-direction: column;\n    justify-content: flex-end;\n    align-items: center;\n\n    cursor: pointer;\n\n    font-size: 2rem;\n    svg {\n        fill: $colour_sunny_side_up_yellow !important;\n        width: 10rem;\n        height: auto;\n    }\n    p {\n        color: $colour_sunny_side_up_yellow !important;\n        margin-top: 0;\n        padding-bottom: 3vh;\n        max-width: 770px;\n        padding-left: 2rem;\n        padding-right: 2rem;\n    }\n}\n","@media only screen and (min-width: 0px) {\n    html {\n        font-size: calc(8px + 0.1vw) !important;\n    }\n    #header {\n        #logo {\n            width: 24vw;\n            height: 24vw;\n            margin-top: calc(24vw * -0.1666666);\n        }\n        h1 {\n            margin-top: 0;\n            font-size: calc(24vw / 3);\n            right: calc(24vw / 2.3);\n            top: calc(24vw / 1.6);\n        }\n    }\n    blockquote.main-quote {\n        padding-left: calc(2rem + 3vw);\n        padding-right: calc(2rem + 3vw);\n        p {\n            text-align: center;\n        }\n    }\n    main#main {\n        // padding-top: calc(24vw * 1.3);\n        padding-left: calc(2rem + 3vw);\n        padding-right: calc(2rem + 3vw);\n        // #content-below-quote {\n        //     margin-left: -3vw;\n        //     margin-right: -3vw;\n        //     padding-left: 3vw;\n        //     padding-right: 3vw;\n        // }\n        .typography h1:before,\n        .typography h2:before {\n            display: none;\n        }\n        .typography {\n            .image-container {\n                img {\n                    max-width: 92%;\n                    width: 100%;\n                }\n            }\n        }\n    }\n    footer#footer {\n        margin-top: 160vh;\n        #theme-selectors {\n            display: block;\n        }\n    }\n}\n\n@media only screen and (min-width: 450px) and (min-height: 400px) {\n    #header {\n        #logo {\n            width: 18vw;\n            height: 18vw;\n            margin-top: calc(18vw * -0.1666666);\n        }\n        h1 {\n            font-size: calc(18vw / 3);\n            right: calc(6vw + (18vw / 4.6));\n            top: calc(18vw / 1.6);\n        }\n    }\n    #nav {\n        #nav-inner {\n            left: 15% !important;\n            margin: 0;\n            nav {\n                & > ul {\n                    li {\n                        padding-left: 0;\n                        margin-left: 0;\n                        ul {\n                            margin-left: 3vw;\n                            li {\n                                font-size: 2rem;\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n    main#main {\n        // #content-below-quote {\n        //     margin-left: -6vw;\n        //     margin-right: -6vw;\n        //     padding-left: 6vw;\n        //     padding-right: 6vw;\n        // }\n        // padding-top: calc(18vw * 1.4);\n        .typography {\n            .image-container {\n                img {\n                    max-width: 92%;\n                }\n            }\n        }\n    }\n    .row {\n        grid-template-columns: 1fr 1fr;\n    }\n    footer#footer {\n        // margin-top: 180vh;\n        padding: 4rem 6vw;\n        #theme-selectors {\n            a {\n                margin-right: 1.5rem;\n                margin-left: 0rem;\n            }\n        }\n        div.col {\n            text-align: left;\n            padding-top: 0;\n        }\n    }\n}\n\n@media only screen and (min-width: 600px) {\n    .card-holder {\n        grid-template-columns: repeat(2, 1fr);\n        grid-column-gap: 2rem;\n    }\n}\n@media only screen and (min-width: 750px) {\n    #header {\n        #logo {\n            width: 12vw;\n            height: 12vw;\n            margin-top: calc(12vw * -0.1666666);\n        }\n        h1 {\n            font-size: calc(12vw / 3);\n            right: calc(6vw + (12vw / 4.6));\n            top: calc(12vw / 1.6);\n        }\n    }\n\n    .row {\n        grid-template-columns: 1fr 1fr;\n    }\n    #nav {\n        .icon {\n            left: -6rem;\n        }\n    }\n    .card-holder {\n        grid-column-gap: 4rem;\n    }\n    footer#footer {\n        padding: 4rem 6vw;\n        // margin-top: 180vh;\n    }\n}\n@media only screen and (min-width: 900px) {\n    #nav {\n        // border-right: 4px dotted #ffffff30!important;\n    }\n    body.past-header:not(.footer-visible) #nav {\n        // border-right: 4px dotted #ffffff45!important;\n    }\n    main#main {\n        .element {\n            h1:before,\n            h2:before {\n                display: block;\n                border-top: 4px dotted $colour_modern_iron;\n            }\n            h1,\n            h2 {\n                padding-top: 1.2rem;\n                margin-top: 0;\n                margin-top: 4px;\n                border-bottom: none;\n                .icon {\n                    margin-top: 0px;\n                }\n            }\n            li {\n                p,\n                h3,\n                h4,\n                h5,\n                h6,\n                form,\n                address,\n                div.captionImage {\n                    margin-left: 0;\n                    padding-left: 0;\n                }\n                ul,\n                ol {\n                    padding-top: 1.7rem;\n                    margin-left: 0 !important;\n                    padding-left: 2.3rem;\n                    padding-bottom: 0;\n                    li {\n                        margin-left: 0rem;\n                        padding-left: 0;\n                    }\n                }\n            }\n            .image-container.full {\n                padding-left: 0 !important;\n                padding-right: 0 !important;\n                img {\n                    max-width: calc(100% - 2px) !important;\n                }\n            }\n            &.dnadesign__elemental__models__elementcontent,\n            &.sunnysideup__app__elements__hostingcalculator {\n                h1,\n                h2 {\n                    clear: left;\n                    float: left;\n                    width: calc(21vw - 5rem);\n                }\n                p,\n                ul,\n                ol,\n                h3,\n                h4,\n                h5,\n                h6,\n                blockquote,\n                address,\n                div.captionImage {\n                    margin-left: 24vw;\n                    padding-top: 0;\n                    margin-top: 0;\n                }\n                h2 + p,\n                h2 + ul,\n                h2 + ol {\n                    padding-top: 1.2rem;\n                }\n                .image-container {\n                    padding-left: 0 !important;\n                    padding-right: 0 !important;\n                    img {\n                        display: block;\n                        margin: 0 0 0 auto;\n                        max-width: calc(64vw - 2px);\n                    }\n                }\n            }\n        }\n    }\n\n    // #SiblingsAndChildren {\n    //     margin-top: 6rem !important;\n    //     padding-top: 2rem !important;\n    // }\n    footer#footer {\n        // margin-top: 180vh;\n    }\n}\n@media only screen and (min-width: 1050px) {\n    body.past-header {\n        #header {\n            opacity: 0;\n            display: none;\n        }\n    }\n    body.past-header.scrolled-up.just-scrolled:not(.menu-on):not(.show-logo) {\n        #header {\n            opacity: 1;\n            display: block;\n            animation-duration: 1s; /* the duration of the animation */\n            animation-timing-function: ease-out; /* how the animation will behave */\n            animation-delay: 7s; /* how long to delay the animation from starting */\n            animation-iteration-count: 1; /* how many times the animation will play */\n            animation-name: unloadTransition; /* the name of the animation we defined above */\n            animation-fill-mode: forwards;\n            border-bottom: 4px dotted  $colour_blue_cobalter_half; //#022866!important;\n        }\n    }\n    body.past-header.just-scrolled.toc-on {\n        #header {\n            display: none !important;\n        }\n    }\n    #header {\n        #logo {\n            width: 9vw;\n            height: 9vw;\n            margin-top: calc(9vw * -0.1666666);\n        }\n        h1 {\n            font-size: calc(9vw / 3);\n            top: calc(9vw / 1.6);\n            a.bread-crumb {\n                font-size: 2.5rem;\n            }\n        }\n    }\n\n    #nav {\n        opacity: 1 !important;\n        border: none;\n        border-radius: 0;\n        margin-left: 0;\n        margin-bottom: 0;\n\n        opacity: 1;\n        position: fixed;\n        left: 0;\n        top: 0;\n        right: auto;\n        bottom: 0;\n        width: 18vw;\n        height: auto;\n        z-index: 20;\n        #menu-toggle {\n            transform: rotate(0);\n            text-align: center;\n            top: calc(50% - (0.5 * (5vw + 7vh) / 2)) !important;\n            left: 0 !important;\n            width: 18vw;\n            svg {\n                height: 5rem !important;\n            }\n        }\n        #nav-inner {\n            left: 40% !important;\n            scrollbar-width: none;\n            -ms-overflow-style: none;\n            &::-webkit-scrollbar {\n                width: 0px;\n            }\n            p {\n                font-size: 1rem;\n            }\n        }\n    }\n    main#main {\n        margin-left: calc(19vw + 7vw);\n        margin-right: 7vw;\n        overflow: visible;\n        // #content-below-quote {\n        //     margin-left: calc((19vw + 7vw) * -1);\n        //     margin-right: -7vw;\n        //     padding-left: calc(19vw + 7vw);\n        //     padding-right: 7vw;\n        // }\n        // padding-top: calc(9vw * 1.5);\n        padding-left: 0;\n        padding-right: 0;\n        blockquote.main-quote {\n            transform: none;\n            p {\n                transform: translateY(-0.95em);\n                margin-top: 0 !important;\n                padding-top: 0 !important;\n                text-align: left;\n                padding-bottom: 0 !important;\n                padding-left: 0 !important;\n                padding-right: 0 !important;\n            }\n        }\n        .typography {\n            .image-container {\n                img {\n                    max-width: calc(43vw - 2px);\n                }\n            }\n        }\n    }\n    footer#footer {