        a,\n                        * {\n                            font-size: 1.5rem !important;\n                        }\n                        ul {\n                            li {\n                                margin-bottom: 2vh;\n                                margin-top: 2vh;\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n",".sunnysideup__app__elements__workexample {\n    .content-element__content {\n        h3 {\n            color: $colour_blue_cobalter_highlights;\n            text-transform: none;\n            padding-left: calc(3rem + 1px) !important;\n            padding-bottom: 0 !important;\n            margin-bottom: 1rem !important;\n            .open-close {\n                display: none !important;\n            }\n        }\n    }\n    .work-example-images {\n        padding-bottom: 4rem;\n        position: relative;\n        a {\n            filter: none;\n        }\n        .image-container {\n            padding-bottom: 1rem !important;\n            img.not-first {\n                margin-top: -3rem !important;\n            }\n        }\n        .dotted-line {\n            position: absolute;\n            width: 50px;\n            border-left: 4px dotted $colour_modern_iron;\n            bottom: 9rem;\n            top: 0;\n            margin-top: -2rem;\n            left: calc(50% + 1px);\n            z-index: -1;\n        }\n        img {\n            box-shadow: 7px 7px 12px 2px rgba(0, 0, 0, 0.5);\n            padding: 2rem;\n            padding-bottom: 5rem;\n            background-color: white;\n            border: 1px solid #aaa;\n            width: calc(100% - 4rem) !important;\n            display: block;\n        }\n        p.caption {\n            margin-top: 0 !important;\n            padding-bottom: 4rem !important;\n            a {\n                text-decoration: none !important;\n                background-color: #fff !important;\n                padding: 0.5rem 1rem;\n                border-radius: 0!important;\n                color: $colour_outer_space_love !important;\n                // border: 1px solid $colour_burned_sunny_side_up;\n                border-bottom: 4px solid $colour_burned_sunny_side_up;\n                font-style: normal;\n            }\n        }\n    }\n}\n",".sunnysideup__app__elements__workexampleall {\n    .content-element__content {\n        .work-example-images {\n            padding-top: 2rem;\n            padding-bottom: 2rem;\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(min(280px, 720px), 1fr));\n            @media only screen and (min-width: 450px) {\n                grid-template-columns: repeat(auto-fit, minmax(min(380px, 720px), 1fr));\n            }\n            justify-content: space-between; /* spread columns to fill row */\n            gap: 5rem; /* vertical spacing (and fallback) */\n            .work-example-image {\n                position: relative;\n                cursor: zoom-in;\n                a {\n                    filter: none;\n                }\n                .image-container {\n                    margin: 0 !important;\n                    padding: 0 !important;\n                    img {\n                        margin: 0 !important;\n                        padding: 0 !important;\n                        display: block !important;\n                        width: 100% !important;\n                        box-sizing: border-box;\n                        border: 1px solid $colour_modern_iron_half;\n                        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.33);\n                        border-radius: 1.3rem;\n                        max-width: 100% !important;\n                    }\n                }\n                .work-example-image-caption {\n                    position: absolute;\n                    background-color: $colour_rose_storm;\n                    padding: 2rem;\n    