y {\n            border-bottom-color: $colour_law_firm_report_cover !important;\n        }\n        .btn-toolbar {\n            input {\n                background: $colour_hypocrite_yellow;\n            }\n        }\n    }\n    #Breadcrumbs {\n        border-color: $colour_white !important;\n    }\n    #footer {\n        background-color: $colour_purple_spirituality_in_the_sun;\n        * {\n            color: $colour_white;\n        }\n        p {\n            color: $colour_white;\n        }\n        #theme-selectors {\n            svg {\n                fill: $colour_white;\n            }\n            #theme-rocket {\n                svg {\n                    fill: $colour_sunny_side_up_yellow;\n                }\n            }\n        }\n    }\n    &.past-header {\n        #header {\n            border-bottom: 1px solid #fff;\n            background-color: hsla(0, 0%, 100%, 0.7);\n            * {\n                color: $colour_black;\n                -webkit-text-stroke-width: 0px;\n            }\n        }\n    }\n    &.no-touch {\n        #footer {\n            opacity: 0.6;\n            &:hover {\n                opacity: 1;\n            }\n        }\n        &.past-header {\n            #header {\n                h1 {\n                    background-color: transparent;\n                }\n            }\n        }\n    }\n}\n\n@media only screen and (min-width: 1050px) {\n    body.theme-rocket {\n        #nav {\n            background-color: $colour_white_ten_percent;\n        }\n        &.menu-on {\n            #nav {\n                background-color: $colour_sunny_side_up_yellow;\n            }\n        }\n        main#main {\n            blockquote.main-quote {\n                margin-right: 7vw;\n                margin-left: calc(19vw + 7vw);\n            }\n        }\n    }\n}\n@media only screen and (min-width: 1350px) {\n    body.theme-rocket {\n        main#main {\n            blockquote.main-quote {\n                margin-right: 11vw;\n        