d_sunny_side_up !important;\n            }\n        }\n        h1,\n        h2 {\n            text-transform: uppercase;\n            color: $colour_blue_cobalter;\n            border-bottom-color: $colour_burned_sunny_side_up_thirty_percent !important;\n        }\n        h2, h3 {\n            color:$colour_hypocrite_yellow_lighter!important;\n            span {\n                color: $colour_hypocrite_yellow_lighter;\n                i {\n                    color: $colour_hypocrite_yellow_lighter;\n                }\n            }\n        }\n        h1,\n        h2 {\n            &:before {\n                border-color: $colour_burned_sunny_side_up_thirty_percent !important;\n            }\n        }\n        pre {\n            background-color: $colour_blue_cobalter;\n            color: $colour_white;\n        }\n        th {\n            color: $colour_hypocrite_yellow_lighter;\n        }\n        td {\n            background-color: $colour_white;\n            color: $colour_darker_grey_catch_22;\n            * {\n                color: $colour_darker_grey_catch_22 !important;\n            }\n        }\n        hr {\n            border-color: $colour_burned_sunny_side_up_thirty_percent !important;\n        }\n        .media,\n        .image-container,\n        blockquote p {\n            background-color: transparent;\n            // background: linear-gradient(to left, $colour_law_firm_report_cover, $colour_outer_space_love, $colour_law_firm_report_cover);\n            background: transparent;\n            border-color: transparent;\n        }\n        img {\n            border-color: $colour_burned_sunny_side_up_thirty_percent;\n        }\n        li {\n            &::marker {\n                color:$colour_hypocrite_yellow_lighter;\n            }\n        }\n        #content-below-quote blockquote p {\n            border-left-color: $colour_burned_sunny_side_up_thirty_percent !important;\n        }\n    }\n\n    form {\n        * {\n            color: $colour_law_firm_report_cover !important;\n        }\n        .middleColumn {\n            input,\n            textarea,\n            select {\n                border-bottom-color: $colour_law_firm_report_cover !important;\n            }\n        }\n        span.readonly {\n            border-bottom-color: $colour_law_firm_report_cover !important;\n        }\n        .btn-toolbar {\n            input {\n                background: $colour_burned_sunny_side_up;\n            }\n        }\n    }\n    .sunnysideup__app__elements__workexample {\n        .content-element__content {\n            h3 {\n                color:$colour_hypocrite_yellow_lighter!important;\n            }\n            .dotted-line {\n                border-color: $colour_burned_sunny_side_up_thirty_percent;\n            }\n            .card-holder {\n                color: #fff;\n                * {\n                    color: #fff;\n                }\n                border-color: $colour_burned_sunny_side_up_thirty_percent;\n            }\n            .work-example-images {\n                p.caption {\n                    a {\n                        color: #333 !important;\n                        &:link,\n                        &:visited {\n                            color: #333 !important;\n                            border-color: $colour_burned_sunny_side_up_thirty_percent;\n                        }\n                    }\n                }\n            }\n        }\n    }\n    #Breadcrumbs {\n        border-color: $colour_burned_sunny_side_up_thirty_percent !important;\n    }\n    footer#footer {\n        background-color: $colour_boot_black_semi;\n        img {\n            // filter: invert(1);\n        }\n        * {\n            color: $colour_white;\n        }\n        p {\n            color: $colour_white;\n        }\n        li.current a,\n        a:hover {\n            color: $colour_ekos_green !important;\n        }\n        #theme-selectors {\n            svg {\n                